import json,statistics,math
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path('results/mnist_gradient_branch_scoring_20261106');rs=json.loads((p/'results.json').read_text());tests=json.loads((p/'test_results.json').read_text());bench=json.loads((p/'clean_benchmark.json').read_text());selected=json.loads((p/'selection.json').read_text())['arm'];summary=[]
ms={arm:statistics.median(r['milliseconds_per_step'] for r in bench if r['arm']==arm) for arm in ['exact','linear','quadratic','hybrid5','hybrid10']}
lines=['# Gradient-based branch scoring and cheaper auxiliary training','', 'Matched sparse MNIST MLP: three seeds × two orders × five methods = 30 training runs. Same 168 neurons × four branches, 196 inputs/branch, 134,074 parameters, about 1.593 MB persistent model state. Two epochs per task; Adam .0005, batch128, clip5; same initialization and batch order. All image-only predictions use fixed soft magnitude weighting of tanh branches.','', '| Method | Image-only validation acc | Clean ms/step | Step speedup | Exact-step fraction | Observed full training s |','|---|---:|---:|---:|---:|---:|']
for arm in ['exact','linear','quadratic','hybrid5','hybrid10']:
 rows=[r for r in rs if r['arm']==arm];vals=[statistics.mean(r['validation_history'][-1]['magnitude_soft']['accuracy']*100 for r in rows if r['seed']==s) for s in [101,102,103]];fraction=statistics.mean(r['exact_steps']/r['steps'] for r in rows);seconds=statistics.mean(r['training_seconds'] for r in rows);r=dict(arm=arm,validation_mean=statistics.mean(vals),validation_seed_sd=statistics.stdev(vals),clean_ms_per_step=ms[arm],clean_step_speedup=ms['exact']/ms[arm],exact_fraction=fraction,training_seconds=seconds);summary.append(r);lines.append(f"| {arm} | {r['validation_mean']:.2f} ± {r['validation_seed_sd']:.2f}% | {ms[arm]:.3f} | {ms['exact']/ms[arm]:.2f}× | {fraction:.1%} | {seconds:.3f} |")
lines+=['',f'Validation-selected approximate method: **{selected}**.','', '| Method | Image-only test acc | Oracle test acc | Label-free state: persistent contexts | Label-free state: mixed stream |','|---|---:|---:|---:|---:|']
for arm in ['exact',selected]:
 rows=[r for r in tests if r['arm']==arm];cells=[]
 for path in [('scores','magnitude_soft','accuracy'),('scores','oracle','accuracy'),('streams','blocked','accuracy'),('streams','mixed','accuracy')]:
  def get(r):
   for k in path:r=r[k]
   return r
  v=[statistics.mean(get(r)*100 for r in rows if r['seed']==s) for s in [101,102,103]];cells.append(f'{statistics.mean(v):.2f} ± {statistics.stdev(v):.2f}%')
 lines.append('| '+arm+' | '+' | '.join(cells)+' |')
differences=[];paired=[]
for r in [r for r in tests if r['arm']==selected]:
 b=next(b for b in tests if b['arm']=='exact' and b['seed']==r['seed'] and b['first']==r['first']);paired.append(dict(seed=r['seed'],first=r['first'],delta_pp=(r['scores']['magnitude_soft']['accuracy']-b['scores']['magnitude_soft']['accuracy'])*100))
for seed in [101,102,103]:differences.append(statistics.mean(r['delta_pp'] for r in paired if r['seed']==seed))
mean=statistics.mean(differences);half=4.30265273*statistics.stdev(differences)/math.sqrt(3)
lines+=['',f'Selected method minus exact, paired seed-level image-only test difference: **{mean:+.2f} pp**; descriptive 95% t interval [{mean-half:+.2f}, {mean+half:+.2f}] pp. Not a prespecified noninferiority test.','', '## Approximation quality on exact-baseline trajectories','', '| Estimate | Batch best-branch agreement | Per-example best-branch agreement | Mean exact-loss regret | Mean loss error |','|---|---:|---:|---:|---:|']
quality=[]
for mode in ['linear','quadratic']:
 qs=[q for r in rs if r['arm']=='exact' for q in r['quality'] if q['approximation']==mode];q={k:statistics.mean(r[k] for r in qs) for k in ['batch_best_branch_agreement','sample_best_branch_agreement','mean_exact_regret','mean_absolute_loss_error','sign_agreement']};q['approximation']=mode;quality.append(q);lines.append(f"| {mode} | {100*q['batch_best_branch_agreement']:.2f}% | {100*q['sample_best_branch_agreement']:.2f}% | {q['mean_exact_regret']:.3g} | {q['mean_absolute_loss_error']:.3g} |")
lines+=['','Quality checks sample every 100 batches of exact training, excluded from training timing. Batch agreement compares minimum mean substitution loss across branches for each neuron; per-example agreement compares each image/neuron. Regret measures true substitution loss above the true best branch when selecting by approximate scores. These checks do not establish approximation quality on arbitrary architectures.','', '## Implementation','', 'For selected hidden output h_i and alternative z_ib, delta=z_ib-h_i. Per-example hidden gradient is g_i = sum_c (p_c-onehot(y)_c) W_ci, the closed-form equivalent of CE backprop through the current linear head. First-order branch score is CE + g_i delta. Quadratic score adds .5 Var_p(W_ci) delta². EMA .95 uses these estimated absolute errors as before.','', 'Auxiliary surrogate is not removed. Exact loss is CE + .5 mean(substitution CE). Taylor replacement is 1.5 CE + .5 mean(g_i delta), adding .25 mean(curvature delta²) for quadratic. Residual probabilities are stopped, but W and delta remain differentiable so the surrogate includes classifier-head updates; a stopped-g-only loss would omit some head gradients. No second backward pass is needed.','', 'Hybrid5 uses exact objective and exact feedback on batches 0,5,10,... and linear surrogate/feedback otherwise. Hybrid10 uses batches 0,10,20,... . Trace and optimizer state never reset. No inverse-frequency loss scaling.','', '## Timing and limits','', '- Clean benchmark: original exact implementation without Taylor/quality calculations, or corresponding cheaper objective, then backward, clip, Adam, trace update. Three rotated method-order repeats, ten warmup steps and 100 measured steps per repeat on CPU two threads. Median step time reported. Reuses one current-task minibatch on one trained checkpoint; this is a local throughput benchmark, not an entire end-to-end application benchmark.','- Observed full training seconds exclude evaluation and quality probes. The exact training-run implementation also computes unused Taylor intermediates; therefore clean benchmark, not full-training ratio, is the primary speed comparison. Hybrid clean benchmark likewise uses the clean exact reference on correction steps.','- No B×neurons×branches×classes alternative-logit tensor is created on approximate steps. Branch responses, sparse projection materialization and normal classification forward/backward remain. Fixed architecture has ten classes; larger-architecture throughput is not measured.','- Closed-form gradient/curvature exploits the linear head. Deeper-layer branch scoring can use local backprop gradients, but this surrogate implementation is not yet a generic deep-network solution.','- All settings were fixed in advance; approximate arm selected on mean validation only; official tests evaluated for exact and selected method. Previously used MNIST test set makes this an exploratory experiment. Three seed-level averages over orders define SD; more seeds needed for precise accuracy claims.','- Inference uses the same algorithms and model size; it is not made faster by cheaper training. Optional short-term-state evaluation still computes its exact label-free counterfactual probes; decay .9 and strength .9 remain fixed without retuning.','- Three tests passed: gradient scale agrees with autograd, second-order correction improves small-perturbation loss approximation, and exact mode reproduces the original auxiliary objective.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n');(p/'summary.json').write_text(json.dumps(summary,indent=2));(p/'quality_summary.json').write_text(json.dumps(quality,indent=2));(p/'paired.json').write_text(json.dumps(paired,indent=2))
fig,ax=plt.subplots(figsize=(8,4.7))
for r in summary:
 ax.errorbar(r['clean_ms_per_step'],r['validation_mean'],yerr=r['validation_seed_sd'],fmt='o',capsize=3);ax.annotate(r['arm'],(r['clean_ms_per_step'],r['validation_mean']),xytext=(5,7),textcoords='offset points')
ax.set_xlabel('Clean training-step time (ms; lower is faster)');ax.set_ylabel('Image-only validation accuracy (%)');ax.set_title('Gradient scoring: sparse four-branch MNIST MLP');ax.grid(alpha=.2);fig.tight_layout();fig.savefig(p/'accuracy_training_time.png',dpi=180);plt.close(fig)
